const listSuperAdminMembershipsInTenant = `-- name: ListSuperAdminMembershipsInTenant :many
SELECT m.id, m.person_id, m.tenant_id, m.status, m.joined_at,
       m.left_at, m.designation, m.department, m.status_message,
       m.reports_to, m.created_by_membership_id
FROM   identity.tenant_memberships m
JOIN   identity.role_assignments  ra ON ra.membership_id = m.id
JOIN   identity.roles             r  ON r.id = ra.role_id
WHERE  m.tenant_id     = $1
  AND  m.status        = 'active'
  AND  r.is_super_admin = true
  AND  NOT r.is_deleted
`

// Returns the active Memberships in the supplied tenant that hold a
// role flagged is_super_admin=true. Powers the platform-tenant
// deletion guard (cmd 20260507000008): a tenant containing any
// SuperAdmin role-holder cannot be soft-deleted via the standard
// tenant lifecycle commands. Queryable in O(1) via the partial index
// idx_roles_super_admin.
func (q *Queries) ListSuperAdminMembershipsInTenant(ctx context.Context, tenantID pgtype.UUID) ([]IdentityTenantMembership, error) {
	rows, err := q.db.Query(ctx, listSuperAdminMembershipsInTenant, tenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []IdentityTenantMembership
	for rows.Next() {
		var i IdentityTenantMembership
		if err := rows.Scan(
			&i.ID,
			&i.PersonID,
			&i.TenantID,
			&i.Status,
			&i.JoinedAt,
			&i.LeftAt,
			&i.Designation,
			&i.Department,
			&i.StatusMessage,
			&i.ReportsTo,
			&i.CreatedByMembershipID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchActiveMembersByName = `-- name: SearchActiveMembersByName :many
SELECT m.id AS membership_id, p.first_name, p.last_name, m.designation
FROM   identity.tenant_memberships m
JOIN   identity.persons p ON p.id = m.person_id
WHERE  m.tenant_id = $1::uuid
  AND  m.status = 'active'
  AND  p.is_active
  AND  NOT p.is_anonymised
  AND  NOT p.is_globally_suspended
  AND  (p.first_name || ' ' || p.last_name) ILIKE $2::text
ORDER  BY lower(p.first_name), lower(p.last_name), m.id
LIMIT  $3
`

type SearchActiveMembersByNameParams struct {
	TenantID pgtype.UUID
	Pattern  string
	Limit    int32
}

type SearchActiveMembersByNameRow struct {
	MembershipID pgtype.UUID
	FirstName    string
	LastName     string
	Designation  string
}

// Member picker (lead reassignment): ACTIVE members of the transaction tenant
// whose display name contains the pattern. Returns the membership id, the
// person's names and the designation, never an email or phone. The pattern is
// built by the caller with LIKE wildcards escaped (backslash is the escape
// character). Persons who are inactive, anonymised or globally suspended are
// not offered. tenant_id is bound explicitly on top of RLS. A tenant's
// active-member set is small, so the match runs over the (tenant_id) range of
// idx_memberships_tenant_active_joined, with no trigram index of its own.
func (q *Queries) SearchActiveMembersByName(ctx context.Context, arg SearchActiveMembersByNameParams) ([]SearchActiveMembersByNameRow, error) {
	rows, err := q.db.Query(ctx, searchActiveMembersByName, arg.TenantID, arg.Pattern, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchActiveMembersByNameRow
	for rows.Next() {
		var i SearchActiveMembersByNameRow
		if err := rows.Scan(
			&i.MembershipID,
			&i.FirstName,
			&i.LastName,
			&i.Designation,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateMembershipProfile = `-- name: UpdateMembershipProfile :exec
UPDATE identity.tenant_memberships
SET    designation    = $2,
       department     = $3,
       status_message = $4,
       reports_to     = $5
WHERE  id = $1
`

type UpdateMembershipProfileParams struct {
	ID            pgtype.UUID
	Designation   string
	Department    string
	StatusMessage string
	ReportsTo     pgtype.UUID
}

// Per-tenant profile fields. designation/department/status_message default
// to ” (NOT NULL DEFAULT ”); reports_to is NULLable (top-of-tree). Caller
// (UpdateByID) writes the aggregate's current state — no per-field diff.
func (q *Queries) UpdateMembershipProfile(ctx context.Context, arg UpdateMembershipProfileParams) error {
	_, err := q.db.Exec(ctx, updateMembershipProfile,
		arg.ID,
		arg.Designation,
		arg.Department,
		arg.StatusMessage,
		arg.ReportsTo,
	)
	return err
}

